      starter: "import csv\nimport json\nfrom dataclasses import dataclass, asdict\nfrom datetime import date\n\n@dataclass\nclass Transaction:\n    date: str\n    description: str\n    amount: float\n    category: str = \"other\"\n\n\ndef parse_amount(text):\n    try:\n        return round(float(text.replace(\",\", \"\")), 2)\n    except ValueError:\n        raise ValueError(f\"Bad amount: {text}\")\n\n\nclass Budget:\n    def __init__(self):\n        self.transactions = []\n        self.limits = {}\n\n    def add(self, transaction):\n        self.transactions.append(transaction)\n\n    def balance(self):\n        return round(sum(t.amount for t in self.transactions), 2)\n",
      hint: "Skip amounts of 0 or more. `t.date.startswith(month)` checks the month. Sort the items by `(-total, category)`.",
      solution: "import csv\nimport json\nfrom dataclasses import dataclass, asdict\nfrom datetime import date\n\n@dataclass\nclass Transaction:\n    date: str\n    description: str\n    amount: float\n    category: str = \"other\"\n\n\ndef parse_amount(text):\n    try:\n        return round(float(text.replace(\",\", \"\")), 2)\n    except ValueError:\n        raise ValueError(f\"Bad amount: {text}\")\n\n\nclass Budget:\n    def __init__(self):\n        self.transactions = []\n        self.limits = {}\n\n    def add(self, transaction):\n        self.transactions.append(transaction)\n\n    def balance(self):\n        return round(sum(t.amount for t in self.transactions), 2)\n\n    def spending_by_category(self, month=None):\n        totals = {}\n        for t in self.transactions:\n            if t.amount < 0 and (month is None or t.date.startswith(month)):\n                totals[t.category] = totals.get(t.category, 0) - t.amount\n        ranked = sorted(totals.items(), key=lambda item: (-item[1], item[0]))\n        return {category: round(total, 2) for category, total in ranked}\n",
