"transactions\": [asdict(t) for t in self.transactions], \"limits\": self.limits}\n        with open(path, \"w\", encoding=\"utf-8\") as f:\n            json.dump(data, f, indent=2)\n\n    @classmethod\n    def load(cls, path):\n        budget = cls()\n        try:\n            with open(path, encoding=\"utf-8\") as f:\n                data = json.load(f)\n        except FileNotFoundError:\n            return budget\n        for item in data[\"transactions\"]:\n            budget.add(Transaction(**item))\n        budget.limits = data[\"limits\"]\n        return budget\n\n    def export_csv(self, path):\n        with open(path, \"w\", newline=\"\", encoding=\"utf-8\") as f:\n            writer = csv.DictWriter(f, fieldnames=[\"date\", \"description\", \"category\", \"amount\"])\n            writer.writeheader()\n            for t in self.transactions:\n                writer.writerow({\"date\": t.date, \"description\": t.description, \"category\": t.category, \"amount\": f\"{t.amount:.2f}\"})\n",
